// Keep the small editable SVG sources and synchronous native renderer in sync.
import { readFile, writeFile } from "node:fs/promises";
const names = ["study", "learn", "attend", "forum"];
const rows = await Promise.all(
  names.map(async (name) => [
    name,
    (await readFile(`assets/illustrations/${name}.svg`, "utf8")).replace(
      /<title>[\s\S]*?<\/title>/g,
      "",
    ),
  ]),
);
await writeFile(
  "assets/illustrations/index.ts",
  "// Generated by scripts/sync-learning-art.mjs from the adjacent editable SVG sources.\nexport const artwork = " +
    JSON.stringify(Object.fromEntries(rows), null, 2) +
    " as const;\n",
);
